BEGIN TRANSACTION;
CREATE TABLE assignments (
  namespace TEXT NOT NULL, policy_name TEXT NOT NULL, subject_kind TEXT NOT NULL,
  subject_id TEXT NOT NULL, subject_name TEXT NOT NULL, relationship TEXT NOT NULL,
  source_path TEXT NOT NULL, mount_path TEXT, mount_type TEXT
);
