CREATE TABLE findings (
  fingerprint TEXT PRIMARY KEY, namespace TEXT NOT NULL,
  rule_id TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL,
  description TEXT NOT NULL, remediation TEXT NOT NULL, finding_kind TEXT NOT NULL,
  object_type TEXT NOT NULL, object_path TEXT NOT NULL, object_name TEXT NOT NULL,
  object_mount_path TEXT, object_mount_type TEXT,
  message TEXT NOT NULL, evidence_json TEXT NOT NULL, related_objects_json TEXT NOT NULL,
  policy_name TEXT, policy_path TEXT, capabilities_json TEXT NOT NULL,
  hcl_line INTEGER, matched_block TEXT
);
CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
