CREATE TABLE mounts (
  namespace TEXT NOT NULL, path TEXT NOT NULL, kind TEXT NOT NULL,
  mount_type TEXT NOT NULL, accessor TEXT, description TEXT, role_path TEXT,
  PRIMARY KEY (namespace, path, kind)
);
