CREATE TABLE warnings (position INTEGER PRIMARY KEY, message TEXT NOT NULL);
CREATE INDEX assignments_policy_idx ON assignments(namespace, policy_name);
CREATE INDEX assignments_subject_idx ON assignments(namespace, subject_kind, subject_id);
CREATE INDEX findings_object_idx ON findings(namespace, object_type, object_path);
CREATE INDEX findings_policy_idx ON findings(namespace, policy_name);
COMMIT;
